-- ===== AUTH module (logout + get-account) ===== INSERT INTO permissions (permission_id, name, api_path, http_method, module, created_at, updated_at, created_by, updated_by, version) SELECT UUID(), 'Auth logout', '/api/v1/auth/logout', 'POST', 'AUTH', NOW(6), NOW(6), 'system', 'system', 0 WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE api_path = '/api/v1/auth/logout' AND http_method = 'POST');
