-- ===== Grant ALL new modules to ADMIN ===== INSERT INTO permission_roles (role_id, permission_id) SELECT r.role_id, p.permission_id FROM roles r JOIN permissions p ON p.module IN ('MANAGEMENT', 'AUTH', 'USER_SELF', 'STORAGE') WHERE r.name = 'ADMIN' AND NOT EXISTS ( SELECT 1 FROM permission_roles pr WHERE pr.role_id = r.role_id AND pr.permission_id = p.permission_id );
-- ===== Grant AUTH + USER_SELF + STORAGE to USER ===== INSERT INTO permission_roles (role_id, permission_id) SELECT r.role_id, p.permission_id FROM roles r JOIN permissions p ON p.module IN ('AUTH', 'USER_SELF', 'STORAGE') WHERE r.name = 'USER' AND NOT EXISTS ( SELECT 1 FROM permission_roles pr WHERE pr.role_id = r.role_id AND pr.permission_id = p.permission_id );
